ee:message.ee:set-payload:
%dw 2.0 output application/json
var body = payload.body."wsValidarCoberturas-RS"
// Fecha simple YYYY/MM/DD → ISO fun formatFecha(f) = if ((f default "") != "") (f replace "/" with "-") ++ "T00:00:00Z" else ""
// Fecha YYYYMMDDHHMMSS → YYYY-MM-DDTHH:MM:SSZ fun formatFechaGis(f) = if ((f default "") != "" and sizeOf(f) == 14) f[0 to 3] ++ "-" ++ f[4 to 5] ++ "-" ++ f[6 to 7] ++ "T" ++ f[8 to 9] ++ ":" ++ f[10 to 11] ++ ":" ++ f[12 to 13] ++ "Z" else ""
--- { fechaSolicitud: formatFecha(body.FechaSolicitud), idNap: body.IdNap, nombreNap: body.NombreNap, mayorista: body.Mayorista,
tecnologias: (body.Tecnologias.Tecnologia match { case t if (t is Object and !(t is Array)) -> [t] else -> body.Tecnologias.Tecnologia }) map (t) -> { tipo: t.Tipo default "", propietario: t.Propietario default "", estratoPredominante: t.EstratoPredominante default "", tipoCobertura: t.TipoCobertura default "", cobertura: t.Cobertura default "", nombreCobertura: t.NombreCobertura default "", tipoArea: t.TipoArea default "", area: t.Area default "", migracionOLT: t.MigracionOLT default "", nombreOLT: t.NombreOLT default "" },
respuestaFactibilidad: { factible: body.RespuestaFactibilidad.Factible default "", tecnologia: body.RespuestaFactibilidad.Tecnologia default "", motivo: body.RespuestaFactibilidad.Motivo default "" },
informacionDireccion: { codigoDireccion: body.InformacionDireccion.CodigoDireccion default "", estrato: body.InformacionDireccion.Estrato default "", codigoLote: body.InformacionDireccion.CodigoLote default "", chip: body.InformacionDireccion.Chip default "", barrio: body.InformacionDireccion.Barrio default "", localidad: body.InformacionDireccion.Localidad default "", estadoGeo: body.InformacionDireccion.EstadoGeo default "", destino: body.InformacionDireccion.Destino default "", tipoDistancia: body.InformacionDireccion.TipoDistancia default "" },
gisRespuestaProceso: { codigoRespuesta: body.GisRespuestaProceso.CodigoRespuesta default "", fechaRespuesta: { date: formatFechaGis(body.GisRespuestaProceso.FechaRespuesta.date) }, codigoError: body.GisRespuestaProceso.CodigoError default "", descripcionError: body.GisRespuestaProceso.DescripcionError default "" } }
